// One way for every edge function to read a key.
//
// Rule: an edge function secret (environment variable) wins; otherwise the value comes from Vault,
// where the app's Settings > API keys page stores what a person enters. Worker secrets and function
// addresses are generated by migrations and are only ever read from Vault, so a function and the cron
// job that wakes it always agree.
//
// Vault is read through the `install_secrets` RPC (service role only), cached for a minute. On a
// database set up before that RPC existed it falls back to the three older readers.
import type { SupabaseClient } from "@supabase/supabase-js";

const TTL_MS = 60_000;
/** A Vault read that failed is tried again this soon (so a database hiccup never hides a key for a minute). */
const FAILED_TTL_MS = 5_000;
/** Never taken from the environment. */
export const isVaultOnly = (name: string) => name.endsWith("_WORKER_SECRET") || /^(RADAR|CREATIVES|LAUNCH|RESEARCH|METRICS)_URL$/.test(name);

type Row = { name: string; value: string | null };
export type Env = (name: string) => string | undefined;
export type KeySource = "env" | "vault";

export interface Keys {
  /** The key's value, or undefined when it isn't set anywhere. */
  get(name: string): Promise<string | undefined>;
  /** The key's value, or throws `error(name)` (default: a plain Error saying where to add it) when it isn't set. */
  need(name: string, error?: (name: string) => Error): Promise<string>;
  /** True when the key is set (environment or Vault). */
  has(name: string): Promise<boolean>;
  /** Which of these keys are set, for a function's /health answer. */
  flags(names: readonly string[]): Promise<Record<string, boolean>>;
  /** Where the value in use comes from: `env` (an edge function secret, which wins) or `vault`; null when unset. */
  source(name: string): Promise<KeySource | null>;
  /** The names of the keys that are set and start with `prefix` (per-app keys such as APPSTACK_API_KEY_<APP>). */
  withPrefix(prefix: string): Promise<string[]>;
  /** Forget cached Vault values (after a key is saved). */
  clear(): void;
}

/**
 * `env` reads one environment variable and `envNames` lists them all; both default to the function's
 * own environment and are arguments so tests can pass a fake.
 */
export function createKeys(
  db: SupabaseClient,
  env: Env = (name) => Deno.env.get(name),
  envNames: () => string[] = () => Object.keys(Deno.env.toObject()),
): Keys {
  let cache: { until: number; values: Map<string, string> } | null = null;

  async function vault(): Promise<Map<string, string>> {
    if (cache && Date.now() < cache.until) return cache.values;
    const values = new Map<string, string>();
    const take = (rows: Row[] | null | undefined) => {
      for (const row of rows ?? []) if (row.value?.trim()) values.set(row.name, row.value.trim());
    };
    let read = false;
    const current = await db.rpc("install_secrets");
    if (!current.error) {
      take(current.data as Row[]);
      read = true;
    } else {
      // A database from before the install migration: the three readers it replaced.
      const older = await Promise.all([db.rpc("radar_secrets"), db.rpc("launch_secrets"), db.rpc("research_secrets")]);
      for (const answer of older) {
        if (answer.error) continue;
        take(answer.data as Row[]);
        read = true;
      }
    }
    cache = { until: Date.now() + (read ? TTL_MS : FAILED_TTL_MS), values };
    return values;
  }

  const fromEnv = (name: string) => (isVaultOnly(name) ? undefined : env(name)?.trim() || undefined);

  async function get(name: string): Promise<string | undefined> {
    return fromEnv(name) ?? (await vault()).get(name);
  }

  return {
    get,
    async need(name, error = (missing) => new Error(addKeyMessage(missing))) {
      const value = await get(name);
      if (!value) throw error(name);
      return value;
    },
    async has(name) { return Boolean(await get(name)); },
    async flags(names) {
      const out: Record<string, boolean> = {};
      for (const name of names) out[name] = Boolean(await get(name));
      return out;
    },
    async source(name) {
      if (fromEnv(name)) return "env";
      return (await vault()).has(name) ? "vault" : null;
    },
    async withPrefix(prefix) {
      const found = new Set<string>();
      for (const name of envNames()) if (name.startsWith(prefix) && fromEnv(name)) found.add(name);
      for (const name of (await vault()).keys()) if (name.startsWith(prefix)) found.add(name);
      return [...found].sort();
    },
    clear() { cache = null; },
  };
}

/** What each key is called in the app, for messages that tell a person what to add. */
const KEY_LABELS: Record<string, string> = {
  OPENAI_API_KEY: "your OpenAI key",
  TYPESAFE_API_KEY: "your TypeSafe key",
  APIFY_TOKEN: "your Apify token",
  META_AD_LIBRARY_TOKEN: "your Meta Ad Library token",
  META_SYSTEM_USER_TOKEN: "your Meta system user token",
  META_APP_SECRET: "your Meta app secret",
  REVENUECAT_API_KEY: "your RevenueCat key",
  APPSTACK_API_KEY: "your AppStack key",
  HIGGSFIELD_API_KEY: "your Higgsfield key",
  GOOGLE_SERVICE_ACCOUNT_JSON: "your Google Drive service account",
  CREATIVES_RUNNER_SECRET: "the desktop runner's secret",
  TIKTOK_RESEARCH_CLIENT_KEY: "your TikTok research client key",
  TIKTOK_RESEARCH_CLIENT_SECRET: "your TikTok research client secret",
};

/** "your OpenAI key" for OPENAI_API_KEY; the name itself for a key the app has no label for. */
export const keyLabel = (name: string) => KEY_LABELS[name] ?? (name.startsWith("APPSTACK_API_KEY_") ? KEY_LABELS.APPSTACK_API_KEY : name);

/** The sentence shown when a key is missing: what to add and where. */
export const addKeyMessage = (name: string) => `Add ${keyLabel(name)} in Settings > API keys.`;

/** Compares two secrets without leaking where they differ. Never equal when either is empty. */
export function sameSecret(a: string, b: string): boolean {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}
